# This script parses the changelog file in the repo and writes the notes for the latest
# tag to a specified output file. The idea is that after the changelog file has been
# updated, this script is used to extract the changelog for just the most recent release
# into a format that can be used to populate the Github release's body.
# python3 WriteReleaseNotes.py <changelogPath> <outputFilePath>

from pathlib import Path
import sys
import re

CHANGELOG = Path(sys.argv[1])
OUTPUT_FILE = Path(sys.argv[2])

with open(CHANGELOG, 'r') as file:
    changelog_content = file.readlines()

def find_last_version_heading():
    for idx, line in enumerate(reversed(changelog_content)):
        if re.match('^(##)+', line):
            return len(changelog_content) - idx - 1

    raise ValueError('Version heading (##) not found in changelog text')

start_line_idx = find_last_version_heading()

release_notes = changelog_content[start_line_idx:]

with open(OUTPUT_FILE, 'w') as file:
    file.write(''.join(release_notes))
